const input = $input.first().json || {};
const runType = String(input.requestedRunType || input.runType || '').toUpperCase();
const cfg = input.centralConfig || {};
const globalCfg = cfg.globalConfig || {};
const groqApiKey = globalCfg.groqApiKey || '';
const groqModel = globalCfg.groqModel || 'llama-3.3-70b-versatile';
const channelKey = input.channelKey || 'localStackAi';
const channels = cfg.channels || {};
const channel = channels[channelKey] || {};
const mainOfferUrl = channel.mainOfferUrl || globalCfg.mainOfferUrl || '';
const isDemo = !groqApiKey || groqApiKey === '' || groqApiKey.startsWith('demo-');
const isDemoSheet = !(globalCfg.googleSheetId) || (globalCfg.googleSheetId || '').startsWith('1abcdef');
const supported = ['ANALYTICS_24H', 'ANALYTICS_72H', 'ANALYTICS_7D'];
if (!supported.includes(runType)) {
  return [{ json: { ...input, status: 'ANALYTICS_SKIPPED', analyticsSummary: 'Unsupported analytics runType: ' + (runType || 'UNKNOWN'), completedAt: new Date().toISOString() } }];
}
const windowMap = { ANALYTICS_24H: { hours: 24, label: '24h' }, ANALYTICS_72H: { hours: 72, label: '72h' }, ANALYTICS_7D: { hours: 168, label: '7d' } };
const win = windowMap[runType];
// Demo video data — realistic seed for testing
const demoVideoData = [
  { title: 'How to automate local business follow-ups for free', views: 1240, watchTimeMinutes: 4820, ctr: 9.2, likes: 87, comments: 23, subscribersGained: 34, offerClicks: 28, revenue: 0, postedHoursAgo: 20 },
  { title: '5 free CRM alternatives for service businesses', views: 3400, watchTimeMinutes: 14200, ctr: 11.4, likes: 210, comments: 41, subscribersGained: 89, offerClicks: 71, revenue: 0, postedHoursAgo: 68 },
  { title: 'Review system automation walkthrough', views: 890, watchTimeMinutes: 3100, ctr: 6.1, likes: 44, comments: 12, subscribersGained: 15, offerClicks: 9, revenue: 0, postedHoursAgo: 168 },
  { title: 'Shorts: missed call text back in 60 seconds', views: 8900, watchTimeMinutes: 5200, ctr: 14.2, likes: 440, comments: 88, subscribersGained: 210, offerClicks: 55, revenue: 0, postedHoursAgo: 72 },
  { title: 'Booking automation for plumbers (full setup)', views: 2100, watchTimeMinutes: 9800, ctr: 8.7, likes: 130, comments: 29, subscribersGained: 52, offerClicks: 38, revenue: 0, postedHoursAgo: 120 }
];
const allVideos = isDemoSheet ? demoVideoData : (input.analyticsRows || demoVideoData);
const totalViews = allVideos.reduce((s, v) => s + (v.views || 0), 0);
const totalSubs = allVideos.reduce((s, v) => s + (v.subscribersGained || 0), 0);
const totalOfferClicks = allVideos.reduce((s, v) => s + (v.offerClicks || 0), 0);
const avgCtr = allVideos.length > 0 ? (allVideos.reduce((s, v) => s + (v.ctr || 0), 0) / allVideos.length).toFixed(2) : '0';
const avgWatchTime = allVideos.length > 0 ? Math.round(allVideos.reduce((s, v) => s + (v.watchTimeMinutes || 0), 0) / allVideos.length) : 0;
const totalRevenue = allVideos.reduce((s, v) => s + (v.revenue || 0), 0);
const scoredVideos = allVideos.map(v => ({
  ...v,
  performanceScore: Math.round(
    ((v.subscribersGained || 0) / Math.max(totalSubs, 1)) * 40 +
    ((v.ctr || 0) / 20) * 30 +
    ((v.offerClicks || 0) / Math.max(totalOfferClicks, 1)) * 20 +
    ((v.comments || 0) / Math.max(allVideos.reduce((s, x) => s + (x.comments || 0), 0), 1)) * 10
  )
})).sort((a, b) => b.performanceScore - a.performanceScore);
const topPerformers = scoredVideos.slice(0, 3);
const underperformers = scoredVideos.slice(-2).filter(v => v.performanceScore < 15);
const subsPerDay = (totalSubs / Math.max(win.hours / 24, 1)).toFixed(1);
const offerCvr = totalViews > 0 ? ((totalOfferClicks / totalViews) * 100).toFixed(2) : '0';
const winSignals = [];
if (parseFloat(avgCtr) > 9) winSignals.push('High average CTR ' + avgCtr + '% — thumbnails + titles are working');
if (totalSubs / Math.max(allVideos.length, 1) > 30) winSignals.push('Strong sub-per-video ratio — content resonates with target audience');
if (parseFloat(offerCvr) > 1.5) winSignals.push('Offer CVR ' + offerCvr + '% — CTA placement is converting');
const lossSignals = [];
if (parseFloat(avgCtr) < 6) lossSignals.push('Low CTR < 6% — test new thumbnails and title formulas immediately');
if (avgWatchTime < 3) lossSignals.push('Low avg watch time — hook needs improvement, consider shorter intros');
if (parseFloat(offerCvr) < 0.5) lossSignals.push('Low offer CVR — check CTA copy, URL, and placement in video');
let aiInterpretation = null;
let aiStatus = 'DEMO';
if (!isDemo && !isDemoSheet) {
  try {
    const resp = await fetch('https://api.groq.com/openai/v1/chat/completions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + groqApiKey },
      body: JSON.stringify({
        model: groqModel,
        messages: [{ role: 'user', content: 'YouTube analytics ' + win.label + ' window. Views: ' + totalViews + ', Subs: +' + totalSubs + ', Avg CTR: ' + avgCtr + '%, Avg Watch Time: ' + avgWatchTime + 'min, Offer CVR: ' + offerCvr + '%. Top video: "' + (topPerformers[0] || {}).title + '". Win signals: ' + winSignals.join('; ') + '. Loss signals: ' + lossSignals.join('; ') + '. Return JSON with: interpretation, topAction, doubleDownOn, stopDoing, revenueOpportunity.' }],
        temperature: 0.5,
        max_tokens: 600,
        response_format: { type: 'json_object' }
      })
    });
    if (!resp.ok) throw new Error('Groq ' + resp.status);
    const r = await resp.json();
    aiInterpretation = JSON.parse(r.choices?.[0]?.message?.content || '{}');
    aiStatus = 'GROQ_LIVE';
  } catch(e) {
    aiInterpretation = { _error: String(e.message || e) };
    aiStatus = 'GROQ_ERROR';
  }
}
const top = topPerformers[0] || {};
if (!aiInterpretation || aiStatus === 'DEMO') {
  aiInterpretation = {
    interpretation: win.label + ' window: ' + totalSubs + ' subs at ' + subsPerDay + '/day velocity. ' + (winSignals[0] || 'Building baseline.'),
    topAction: winSignals.length > 0
      ? 'Replicate "' + (top.title || '').slice(0, 50) + '" format — drove ' + (top.subscribersGained || 0) + ' subs'
      : (lossSignals[0] || 'Increase posting to 3 videos/week'),
    doubleDownOn: top.title ? 'Format of: "' + top.title.slice(0, 50) + '"' : 'Tutorial + walkthrough format',
    stopDoing: underperformers.length > 0 ? 'Low-performance format: "' + (underperformers[0].title || '').slice(0, 40) + '"' : 'No clear stop signal yet — keep testing',
    revenueOpportunity: parseFloat(offerCvr) > 1
      ? 'Offer converting at ' + offerCvr + '% — add CTA earlier (at 30% mark) to increase clicks'
      : 'Offer CVR ' + offerCvr + '% is low — test a free lead magnet at ' + mainOfferUrl + ' before the paid ask'
  };
}
const slackDigest = [
  '*' + win.label + ' Analytics — ' + channelKey + '*',
  'Views: ' + totalViews.toLocaleString() + ' | Subs: +' + totalSubs + ' (' + subsPerDay + '/day) | CTR: ' + avgCtr + '%',
  'Offer Clicks: ' + totalOfferClicks + ' | CVR: ' + offerCvr + '%',
  winSignals.length > 0 ? 'Wins: ' + winSignals[0] : '',
  lossSignals.length > 0 ? 'Fix: ' + lossSignals[0] : '',
  'Top Action: ' + aiInterpretation.topAction
].filter(Boolean).join('\n');
return [{ json: {
  ...input,
  status: 'ANALYTICS_COMPLETE',
  aiStatus,
  runType,
  channelKey,
  analyticsWindow: win.label,
  metrics: { totalViews, totalSubs, subsPerDay, avgCtr, avgWatchTime, totalOfferClicks, offerCvr, totalRevenue },
  topPerformers,
  underperformers,
  winSignals,
  lossSignals,
  aiInterpretation,
  slackDigest,
  analyticsSummary: 'Analytics completed for ' + runType + ' [' + aiStatus + ']: ' + totalSubs + ' subs, ' + subsPerDay + '/day velocity',
  completedAt: new Date().toISOString(),
  workflowPackVersion: input.workflowPackVersion || 'v24'
} }];
